CREATE TABLE sync_folder_preserve_delete_resolutions(
 conflict_operation_id TEXT PRIMARY KEY,resolution_operation_id TEXT NOT NULL UNIQUE,folder_id TEXT NOT NULL,expected_revision INTEGER NOT NULL CHECK(expected_revision>0),recovered_folder_id TEXT,recovered_cursor INTEGER,deleted_cursor INTEGER,state TEXT NOT NULL CHECK(state IN ('prepared','resolved')),
 CHECK((state='prepared' AND recovered_folder_id IS NULL AND recovered_cursor IS NULL AND deleted_cursor IS NULL) OR (state='resolved' AND recovered_folder_id IS NOT NULL AND recovered_cursor>0 AND deleted_cursor=recovered_cursor+1)),
 FOREIGN KEY(conflict_operation_id) REFERENCES sync_outbox(operation_id));
CREATE TRIGGER sync_folder_preserve_delete_resolution_insert_guard BEFORE INSERT ON sync_folder_preserve_delete_resolutions WHEN NEW.state<>'prepared' OR NOT EXISTS(SELECT 1 FROM sync_outbox o JOIN sync_conflict_states c ON c.operation_id=o.operation_id WHERE o.operation_id=NEW.conflict_operation_id AND o.object_id=NEW.folder_id AND o.object_type='folder' AND o.mutation='delete' AND o.status='conflict' AND o.conflict_code='base_revision_mismatch' AND c.object_type='folder' AND c.deleted=0 AND c.revision=NEW.expected_revision) BEGIN SELECT RAISE(ABORT,'invalid folder preserve delete resolution'); END;
CREATE TRIGGER sync_folder_preserve_delete_resolution_immutable BEFORE UPDATE OF conflict_operation_id,resolution_operation_id,folder_id,expected_revision ON sync_folder_preserve_delete_resolutions BEGIN SELECT RAISE(ABORT,'folder preserve delete resolution identity immutable'); END;
CREATE TRIGGER sync_folder_preserve_delete_resolution_state_guard BEFORE UPDATE OF state,recovered_folder_id,recovered_cursor,deleted_cursor ON sync_folder_preserve_delete_resolutions WHEN NOT(OLD.state='prepared' AND NEW.state='resolved' AND NEW.recovered_folder_id IS NOT NULL AND NEW.recovered_cursor>0 AND NEW.deleted_cursor=NEW.recovered_cursor+1) BEGIN SELECT RAISE(ABORT,'invalid folder preserve delete resolution transition'); END;
CREATE TRIGGER sync_folder_preserve_delete_resolution_no_delete BEFORE DELETE ON sync_folder_preserve_delete_resolutions BEGIN SELECT RAISE(ABORT,'folder preserve delete resolution durable'); END;
